export const BODY: string = "\n<p>GIF حركة قصيرة متكررة مصنوعة من سلسلة صور ثابتة. تُعرض دون صوت وتتكرر إلى الأبد أو عددًا ثابتًا من المرات، وتعمل في كل تطبيقات المحادثة والخلاصات الاجتماعية والمنتديات تقريبًا.</p>\n<p><a href=\"/ar/munshi-gif/\">صانع GIF</a> يحوّل صورك إلى GIF متحرك في المتصفح. ارفع صورتين أو أكثر كإطارات، وحدد توقيت كل إطار وعدد التكرارات، ونزّل ملف GIF89a جاهزًا للمشاركة.</p>\n<p>يشرح هذا الدليل كيف تعمل GIF وكيف تختار الإطارات وتوقتها، وكيف تبقي حجم الملف صغيرًا بما يكفي للمشاركة. سواء صنعت GIF رد فعل أو عرض منتج أو خطوة تعليمية، ستجد هنا سير العمل.</p>\n<h2 id=\"what-is-a-gif\">ما هو GIF؟</h2>\n<p>GIF تعني صيغة تبادل الرسوم، وهي موجودة منذ أواخر الثمانينيات. إنها من أقدم صيغ الصور التي ما زالت في الاستخدام اليومي، وما زالت حية لأنها بسيطة وشاملة.</p>\n<p>يحفظ GIF سلسلة إطارات، كل منها يُعرض لوقت قصير واحدًا بعد الآخر. والمشغل يمر عبر الإطارات في حلقة، فتبدو النتيجة كمقطع فيديو قصير. ولا صوت ولا أدوات تحكم في التشغيل. وتقتصر GIF على 256 لونًا في الإطار، ولهذا تناسب الرسوم ولقطات الشاشة والحركات البسيطة أكثر من الصور الفوتوغرافية الملونة.</p>\n<h2 id=\"how-the-gif-maker-works\">كيف يعمل صانع GIF</h2>\n<p>صانع GIF يرمّز صورك إلى GIF متحرك بالكامل في متصفحك. إطاراتك لا تغادر جهازك أبدًا، وهذا مهم عندما تكون الصور صور منتجات غير مطلقة أو صورًا شخصية.</p>\n<p>ترفع صورتين أو أكثر كإطارات، والأداة ترتبها. يمكنك إعادة ترتيب الإطارات بالسحب، وتكرار إطار لإبقائه أطول، وحذف إطار لا ينتمي. ولكل إطار تأخيره الخاص، مقاسًا بأجزاء من الثانية. وتأخير قصير يجعل الحركة سريعة، وطويل يجعلها بطيئة.</p>\n<h2 id=\"choosing-frames\">كيف تختار الإطارات</h2>\n<p>الإطارات هي الصور الثابتة التي تشكل الحركة، واختيار الإطارات يقرر هل يعمل GIF. GIF جيد يروي قصة صغيرة: قبل وبعد أو منتج يدور أو خطوة تعليمية.</p>\n<p>استخدم إطارات متشابهة في الحجم والشكل. الأداة تتعامل مع صور بنسب مختلفة، لكن مجموعة إطارات بأبعاد متساوية تعطي حركة ناعمة دون قفزات أو أشرطة. وأبقِ عدد الإطارات معتدلًا: GIF من خمسة إلى خمسة عشر إطارًا يكفي عادة لرد فعل أو عرض أو خطوة تعليمية قصيرة.</p>\n<h2 id=\"frame-delays-and-timing\">تأخيرات الإطارات والتوقيت</h2>\n<p>تأخير الإطار هو مدة بقاء كل إطار على الشاشة، وهو التحكم الرئيسي في إحساس الحركة. تأخير 0.1 ثانية في الإطار يعطي حركة سريعة، وتأخير ثانية كاملة يعطي عرض شرائح بطيئًا.</p>\n<p>استخدم تأخيرًا متسقًا لجسم الحركة وتأخيرًا أطول للإطارات التي تحتاج تأكيدًا. شريحة عنوان في البداية تستحق البقاء أطول لتُقرأ، وإطار أخير يستحق البقاء ليلاحظ المشاهد النتيجة. والإعدادات السريعة لـ1 و2 و5 و10 إطارات في الثانية تعطيك نقاط بداية.</p>\n<h2 id=\"frame-rate-presets\">إعدادات معدل الإطارات المسبقة</h2>\n<p>الإعدادات المسبقة تحوّل الإطارات في الثانية إلى تأخيرات. إطار واحد في الثانية يعني أن كل إطار يُعرض ثانية، وهذا يناسب عرض صور ثابتة حيث تستحق كل صورة نظرة كاملة.</p>\n<p>خمسة إطارات في الثانية تعني خُمس ثانية في الإطار، وهي النقطة المثالية لمعظم GIF. سريعة بما يكفي لتبدو كحركة وبطيئة بما يكفي ليسجل كل إطار. وعشرة إطارات في الثانية تعني عُشر ثانية في الإطار، وهي أنعم ما تقدمه الأداة وتناسب حركات يجب أن تبدو ناعمة مثل الدوران أو دورة المشي.</p>\n<h2 id=\"loop-options\">خيارات التكرار</h2>\n<p>التكرار يقرر عدد مرات تشغيل GIF. الحلقة اللانهائية تُعرض إلى الأبد، وهو السلوك الكلاسيكي لـGIF والخيار الصحيح لردود الفعل والزخارف وكل ما يجب أن يستمر في الحركة.</p>\n<p>الحلقة المحدودة تُعرض عددًا ثابتًا من المرات ثم تتوقف عند الإطار الأخير. هذا يناسب تعليمًا أو عرضًا حيث يجب أن ينتهي الشخص في الحالة النهائية لا في البداية. وعرض واحد يعرض الحركة مرة ويتوقف، ويناسب رسالة حيث الحركة كشف فريد مثل قبل وبعد يجب أن ينتهي في البعد.</p>\n<h2 id=\"frame-fit-contain-vs-cover\">ملاءمة الإطار: احتواء مقابل تغطية</h2>\n<p>ملاءمة الإطار تقرر ما يحدث عندما تختلف نسب الإطارات. الاحتواء يناسب كل إطار داخل حجم الإخراج دون قص، فيُرى الإطار كاملًا وقد تظهر أشرطة فارغة على الجانبين.</p>\n<p>التغطية تملأ حجم الإخراج تمامًا بقص الإطار، فلا أشرطة فارغة لكن حواف الإطار قد تُقص. تعطي حركة نظيفة ممتلئة على حساب فقدان بعض الحواف. واختر الاحتواء عندما يهم كل جزء من كل إطار، مثل تعليم حيث زر مقصوص يخفي الخطوة. واختر التغطية عندما يجب أن تملأ الحركة الإطار نظيفًا.</p>\n<h2 id=\"output-size-and-dimensions\">حجم الإخراج والأبعاد</h2>\n<p>عرض الإخراج يحدد عرض البكسل لـGIF المكتمل، والارتفاع يعتمد على نسبة الإطارات. عرض 480 بكسل خيار شائع للمحادثة والمشاركة الاجتماعية.</p>\n<p>الأصغر أفضل غالبًا لـGIF. GIF بعرض 480 بكسل صغير بما يكفي ليُشارك بسرعة وكبير بما يكفي ليُرى بوضوح على هاتف. وGIF بعرض 1000 بكسل فيه أربعة أضعاف بكسلات نسخة 500 بكسل، وتطبيق المحادثة سيصغّره على أي حال. وراجع الأبعاد مقابل الوجهة قبل التصدير.</p>\n<h2 id=\"color-palette-quality\">جودة لوحة الألوان</h2>\n<p>تحفظ GIF 256 لونًا كحد أقصى في الإطار، فيجب على المرمّز اختيار أي الألوان يحتفظ بها. والتحكم في جودة لوحة الألوان يقرر مدى عناية ذلك الاختيار.</p>\n<p>جودة أعلى تعطي تدرجات أنعم ودرجات بشرة أدق، لكنها تستغرق وقتًا أطول في الترميز وقد تنتج ملفًا أكبر قليلًا. وجودة أقل ترمّز أسرع وتعطي ملفات أصغر، لكن التدرجات قد تظهر خطوطًا. وللصور الفوتوغرافية، استخدم جودة لوحة عالية، فالصور فيها آلاف الألوان واللوحة الدقيقة تبقي الصورة معروفة.</p>\n<h2 id=\"large-gif-warning\">تحذير GIF الكبير</h2>\n<p>تعرض الأداة تحذير GIF كبير عندما يتجاوز الحجم المقدر 5 ميغابايت أو 15 ميغابايت. هذه العتبات موجودة لأن GIF الكبيرة صعبة المشاركة: تُحمَّل ببطء في المحادثات وتستهلك بيانات الجوال وتتجاوز حدود الرفع.</p>\n<p>يصبح GIF كبيرًا لثلاثة أسباب: إطارات كثيرة أو أبعاد كبيرة أو معدل إطارات عالٍ. قص أي منها يصغّر الملف. وعندما يظهر التحذير، قلل عرض الإخراج أولًا: تقليل العرض إلى النصف يقطع عدد البكسلات إلى الربع، وهو أكبر توفير متاح. ثم قلل عدد الإطارات، ثم المعدل.</p>\n<h2 id=\"transparency-in-gifs\">الشفافية في GIF</h2>\n<p>تدعم GIF الشفافية، لكن فقط كلون شفاف واحد لا قناة ألفا ناعمة. البكسل إما شفاف تمامًا أو معتم تمامًا، فالحواف الناعمة والظلال تصبح صلبة.</p>\n<p>صانع GIF يحافظ على الخلفيات الشفافة لإطارات PNG عندما تكون الإخراج مضبوطًا لذلك. شعار أو ملصق بشفافية يحافظ على مناطقه الشفافة، وهذا مفيد لملصقات المحادثة. والحواف الناعمة تحتاج عناية: شعار بظل أو حافة مموّهة سيظهر هالة عندما تُختزل الشفافية إلى لون واحد.</p>\n<h2 id=\"common-mistakes\">الأخطاء الشائعة</h2>\n<p>الخطأ الأكثر شيوعًا هو إطارات كثيرة جدًا. GIF من خمسين إطارًا فيديو متنكر، وسيكون ثقيلًا وبطيئًا ومملًا. قص قائمة الإطارات إلى اللحظات الأساسية وسيتحسن GIF فورًا.</p>\n<p>من الأخطاء الأخرى تأخير موحد لكل إطار. شريحة عنوان معروضة عُشر ثانية لا يمكن قراءتها، وإطار أخير معروض عُشر ثانية لا يمكن ملاحظته. والخطأ الثالث حجم إخراج هائل: GIF مصدّر بعرض 1000 بكسل لرسالة محادثة فيه أربعة أضعاف بكسلات نسخة 500 بكسل.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق لصانع GIF</h2>\n<p>اختر خمسة إلى خمسة عشر إطارًا بأبعاد متساوية، ورتبها بترتيب القصة، وحدد تأخيرًا أساسيًا نحو خمسة إطارات في الثانية. وأعطِ إطارات العنوان والنهاية تأخيرًا أطول لتُقرأ وتُلاحظ.</p>\n<p>حدد عرض الإخراج للوجهة، واستخدم الاحتواء عندما يهم كل تفصيل والتغطية عندما يجب أن يمتلئ الإطار نظيفًا، وارفع جودة اللوحة للصور الفوتوغرافية. وانتبه لتحذير GIF الكبير: إذا ظهر، قلل العرض أولًا.</p>\n<p>للإنشاء خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-ins-ha-gif-min-as-suwar/\">كيف تنشئ GIF من صور</a>، ولتوازن الحجم بالتفصيل اقرأ <a href=\"/ar/blog/muaddal-itarat-gif-wa-hajm-al-malaf/\">معدل إطارات GIF وحجم الملف: الناعم مقابل الصغير</a>. وأنشئ GIF مع <a href=\"/ar/munshi-gif/\">صانع GIF</a>، وصغّر مكتملًا مع <a href=\"/ar/daght-gif/\">ضاغط GIF</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما هو GIF وكيف يختلف عن الفيديو؟","answer":"GIF سلسلة صور ثابتة تُعرض في حلقة، دون صوت ودون أدوات تحكم في التشغيل. الفيديو يستخدم مرمّزًا لضغط الحركة والصوت في ملف أصغر بكثير. GIF أكبر حجمًا لكنها تعمل في كل مكان دون مشغل."},{"question":"كم إطارًا يجب أن يحمل GIF؟","answer":"خمسة إلى خمسة عشر إطارًا تكفي لمعظم GIF: رد فعل أو عرض منتج أو خطوة تعليمية قصيرة. إطارات أكثر تعني حركة أطول وملفًا أكبر. وإذا كان GIF يبدو كفيديو، فقص الإطارات إلى اللحظات الأساسية."},{"question":"لماذا تكون ملفات GIF كبيرة جدًا؟","answer":"تحفظ GIF كل إطار كصورة كاملة بلوحة 256 لونًا، وتضغط بشكل سيئ مقارنة بالفيديو. إطارات كثيرة وأبعاد كبيرة ومعدل عالٍ تجمع الحجم. قلل العرض أولًا، ثم قص الإطارات، ثم اخفض المعدل."},{"question":"هل يمكنني إنشاء GIF من فيديو؟","answer":"صانع GIF يبني GIF من صور ثابتة لا من ملفات فيديو. ولتحويل فيديو إلى GIF، استخرج أولًا سلسلة إطارات ثابتة من الفيديو، ثم ارفع تلك الإطارات كإطارات GIF."},{"question":"هل تعمل GIF في كل منصات التواصل؟","answer":"في كلها تقريبًا، فتطبيقات المحادثة والخلاصات الاجتماعية والمنتديات والبريد تعرض GIF دون مشغل خاص. بعض المنصات تحوّل GIF المرفوعة إلى فيديو تلقائيًا، لكن الحركة تتكرر كما هي."},{"question":"ما أفضل حجم لـGIF؟","answer":"نحو 480 بكسل عرضًا قيمة افتراضية جيدة للمحادثة والمشاركة الاجتماعية: صغيرة بما يكفي لتُرسل بسرعة وكبيرة بما يكفي لتُرى بوضوح على هاتف. واستخدم عرضًا أكبر فقط عندما يحتاجه الوجهة، مثل لافتة موقع."}];
